			/**
			 * getUnitSystemRegionInst
			 */
			function getUnitSystemRegionInst() {
			    var dsOrganization = app.lookup("dsOrganization");
			    dsOrganization.clearFilter();
			    
			    var dsOrgRegionSido = app.lookup("dsOrgRegionSido");
			    // var dsOrgRegionSgg = app.lookup("dsOrgRegionSgg");
			    var dsOrgRegion = app.lookup("dsOrgRegion");
			    
			    dsOrgRegionSido.clear();
			    // dsOrgRegionSgg.clear();
			    
			    var rowDatas = dsOrgRegion.getRowDataRanged();
			    //console.log("rowDatas.length", rowDatas.length);
			    var arrTmp = new Array();
			    for (var i = 0; i < rowDatas.length; i++) {
			        if (arrTmp.indexOf(rowDatas[i]["ENG_CTPV_NM"]) == -1) {
			            var newRowData = {
			                "CTPV_NM": rowDatas[i]["CTPV_NM"],
			                "ENG_CTPV_NM": rowDatas[i]["ENG_CTPV_NM"],
			                "SGG_CD": rowDatas[i]["SGG_CD"].substring(0, 2)
			            };
			            //console.log("newRowData", newRowData);
			            dsOrgRegionSido.pushRowData(newRowData);
			            dsOrgRegionSido.commit();
			            arrTmp.push(rowDatas[i]["ENG_CTPV_NM"]);
			        }
			    }
			}

