			        var cnvrsnScore9 = ValueUtil.fixNumber(dsCaseJgmt.getValue(9, "CNVRSN_SCORE"));
			        var cnvrsnScore13 = ValueUtil.fixNumber(ipbCnvrsnScore13.value);
